dtsPropsFor.Button:
/** `default` : une touche biseautée au trait discret. `primary` : la confirmation, le seul bouton plein — d'os, texte couleur du vide. `danger` : le geste destructeur, teinte des refus. `ghost` : sans cadre, pour « Annuler ». */
  variant?: "default" | "primary" | "danger" | "ghost";
  size?: "sm" | "md";
  /** Une icône avant le libellé. */
  icon?: "eye" | "eyeOff" | "check" | "user" | "userPlus" | "message" | "link" | "mail" | "shield" | "ban" | "unban" | "impersonate" | "logout" | "trash" | "key" | "pencil" | "plus" | "close" | "search" | "copy" | "previous" | "next" | "first" | "last" | "play" | "pause" | "rotateLeft" | "rotateRight" | "cube";
  type?: "button" | "submit" | "reset";
  disabled?: boolean;
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  title?: string;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.IconButton:
icon: "eye" | "eyeOff" | "check" | "user" | "userPlus" | "message" | "link" | "mail" | "shield" | "ban" | "unban" | "impersonate" | "logout" | "trash" | "key" | "pencil" | "plus" | "close" | "search" | "copy" | "previous" | "next" | "first" | "last" | "play" | "pause" | "rotateLeft" | "rotateRight" | "cube";
  /** Le libellé accessible, montré en infobulle au survol. Obligatoire : une icône seule ne dit rien. */
  label: string;
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  /** Le geste est destructeur : la teinte des refus au survol. */
  danger?: boolean;
  /** Rend le bouton inactif et remplace l'infobulle par la raison. Préférer ceci à `disabled` seul. */
  disabledReason?: string;
  disabled?: boolean;
  /** Ancre l'infobulle à droite quand le bouton touche le bord droit d'un conteneur. */
  tipAlign?: "center" | "end";
  type?: "button" | "submit";
  className?: string;

